/* Treadspace +1 clickable concept demonstration. Self-contained, simulated workflows. */
(() => {
  'use strict';
  const D = window.TS_DATA;
  const STORAGE = 'treadspace-plus-one-demo-v4';
  const defaults = {role:'employee', day:1, section:'journey',scenario:'support',checks:{},resourceDone:{},resourcePlan:{},approvals:{},notes:[],activities:[],messages:[],buddyChat:[],supportComplete:false,followUpScheduled:false,selectedTicket:'option-1',filters:{resource:''}, tourIndex:0};
  let state;
  try {state={...defaults,...JSON.parse(localStorage.getItem(STORAGE)||'{}')};} catch {state={...defaults};}
  if(!D.roles[state.role])state.role='employee';
  if(!D.days.includes(+state.day))state.day=1;
  let overlay=null, mobileOpen=false, toastTimeout=null;
  const app=document.getElementById('app'),overlayRoot=document.getElementById('overlay-root'),toastRoot=document.getElementById('toast-root');
  function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{}}
  function esc(s){return String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));}
  function i(name,size=17){
    const p={
      'compass':'<circle cx="12" cy="12" r="9"/><path d="m16.2 7.8-3 5.4-5.4 3 3-5.4z"/>','book-open':'<path d="M12 7v14M3 18V5a2 2 0 0 1 2-2h4a3 3 0 0 1 3 3v15a3 3 0 0 0-3-3H3zm18 0V5a2 2 0 0 0-2-2h-4a3 3 0 0 0-3 3v15a3 3 0 0 1 3-3h6z"/>','target':'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>','layers':'<path d="m12 2 9 5-9 5-9-5 9-5zM3 12l9 5 9-5M3 17l9 5 9-5"/>','flag':'<path d="M4 22V4m0 1c5-4 9 4 16 0v11c-7 4-11-4-16 0"/>','users':'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8m8-7a4 4 0 0 1 0 8"/>','layout-dashboard':'<rect x="3" y="3" width="7" height="9" rx="1"/><rect x="14" y="3" width="7" height="5" rx="1"/><rect x="14" y="12" width="7" height="9" rx="1"/><rect x="3" y="16" width="7" height="5" rx="1"/>','life-buoy':'<circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="4"/><path d="m4.93 4.93 4.24 4.24m5.66 5.66 4.24 4.24M14.83 9.17l4.24-4.24M9.17 14.83l-4.24 4.24"/>','chart':'<path d="M3 3v18h18M7 16v-4m5 4V8m5 8V5"/>','headphones':'<path d="M3 14v-3a9 9 0 0 1 18 0v3M3 14h4v7H5a2 2 0 0 1-2-2zm18 0h-4v7h2a2 2 0 0 0 2-2z"/>','notebook':'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 7h6M9 11h6M9 15h4M3 7h4M3 12h4M3 17h4"/>','sparkles':'<path d="m12 3 1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8L12 3zM19 18l1 2.5 2.5 1-2.5 1-1 2.5-1-2.5-2.5-1 2.5-1zM4 2l.8 2.2L7 5l-2.2.8L4 8l-.8-2.2L1 5l2.2-.8z"/>','alert-triangle':'<path d="m10.3 3.9-8.4 14.4A2 2 0 0 0 3.6 21h16.8a2 2 0 0 0 1.7-2.7L13.7 3.9a2 2 0 0 0-3.4 0zM12 9v4m0 4h.01"/>','calendar':'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>','chevron-right':'<path d="m9 18 6-6-6-6"/>','chevron-left':'<path d="m15 18-6-6 6-6"/>','check':'<path d="m5 12 4 4L19 6"/>','check-circle':'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>','clock':'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>','plus':'<path d="M12 5v14M5 12h14"/>','arrow-right':'<path d="M5 12h14m-6-6 6 6-6 6"/>','arrow-left':'<path d="M19 12H5m6-6-6 6 6 6"/>','x':'<path d="M18 6 6 18M6 6l12 12"/>','eye':'<path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7-10-7-10-7z"/><circle cx="12" cy="12" r="3"/>','bell':'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-8 12a2 2 0 0 0 4 0"/>','send':'<path d="m22 2-7 20-4-9-9-4 20-7ZM22 2 11 13"/>','message':'<path d="M21 11.5a8.4 8.4 0 0 1-9 8.5 9 9 0 0 1-4-.9L3 21l1.9-5A9 9 0 0 1 4 12a8.5 8.5 0 0 1 17-.5z"/>','menu':'<path d="M3 6h18M3 12h18M3 18h18"/>','external':'<path d="M13 4h7v7M20 4l-9 9M20 13v6a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1h6"/>','edit':'<path d="m16 5 3 3M4 20l4.5-1 11-11a2.12 2.12 0 0 0-3-3l-11 11L4 20z"/>','lock':'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>','info':'<circle cx="12" cy="12" r="9"/><path d="M12 11v5m0-9v.01"/>','file':'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zm0 0v6h6M8 13h8M8 17h8"/>','code':'<path d="m8 8-4 4 4 4m8-8 4 4-4 4M14 4l-4 16"/>','refresh':'<path d="M20 11a8 8 0 0 0-14.5-4.5L3 9m0-6v6h6m-5 4a8 8 0 0 0 14.5 4.5L21 15m0 6v-6h-6"/>','play':'<path d="m7 4 14 8-14 8V4z"/>','more':'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>','download':'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>','copy':'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"/>','search':'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>','graduation':'<path d="m2 10 10-5 10 5-10 5-10-5zM6 12v5c4 3 8 3 12 0v-5M22 10v7"/>','shield':'<path d="M12 2 20 6v6c0 5-4 9-8 10-4-1-8-5-8-10V6zM9 12l2 2 4-4"/>','briefcase':'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 13h18"/>'
    };
    return `<svg class="ic" xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]||p.info}</svg>`;
  }
  const button=(text,act,id='',kind='',extra='')=>`<button type="button" class="btn ${kind}" data-action="${esc(act)}" ${id!==''?`data-id="${esc(id)}"`:''} ${extra}>${text}</button>`;
  const card=(title,body,extra='')=>`<section class="panel panel-pad ${extra}"><h3 class="panel-title">${title}</h3>${body}</section>`;
  const pill=(text,variant='indigo')=>`<span class="pill ${variant}">${text}</span>`;
  const row=(title,detail,ic='check')=>`<div class="line-item">${i(ic,15)}<div><b>${esc(title)}</b>${detail?`<div class="small muted">${esc(detail)}</div>`:''}</div></div>`;
  const resourceById=id=>D.resources.find(x=>x.id===id);
  const taskById=id=>D.tasks.find(x=>x.id===id);
  const sectionName=()=>D.navigation[state.role].find(n=>n[0]===state.section)?.[1]||D.roles[state.role].hero;
  function logActivity(label){state.activities.unshift({time:new Date().toLocaleString(),role:state.role,day:state.day,label});state.activities=state.activities.slice(0,60);save();}
  function toast(msg){toastRoot.innerHTML=`<div class="toast">${i('check-circle',16)} ${esc(msg)}</div>`;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>toastRoot.innerHTML='',3700);}
  function setRole(role){if(!D.roles[role])return;state.role=role;state.section='journey';save();overlay=null;render();}
  function setDay(day){day=Number(day);if(!D.days.includes(day))return;state.day=day;state.section='journey';save();overlay=null;render();window.scrollTo({top:0,behavior:'smooth'});}
  function setSection(sec){if(!D.navigation[state.role].some(x=>x[0]===sec))return;state.section=sec;save();overlay=null;render();}
  function avatar(role,large=false){if(role==='employee')return `<span class="mini-avatar photo" style="${large?'height:64px;width:64px;border-radius:15px':''}"><img src="assets/ranvijay.png" alt="Illustrative profile" /></span>`;return `<span class="mini-avatar ${role==='buddy'?'buddy':''}" style="${large?'height:64px;width:64px;font-size:20px;border-radius:15px':''}">${D.roles[role].initials}</span>`;}
  function sidebar(){const role=D.roles[state.role];return `<aside class="sidebar ${mobileOpen?'open':''}"><div class="brand">Treadspace <span class="brand-plus">+1</span></div><div class="side-label">${role.subtitle}</div><nav class="side-nav" aria-label="${role.label} sections">${D.navigation[state.role].map(([key,label,ic])=>`<button class="side-link ${state.section===key?'active':''}" data-action="section" data-id="${key}" title="${label}">${i(ic,17)}<span class="labeltext">${label}</span></button>`).join('')}<button class="side-explore" data-action="explorer" title="Explore every role and day">${i('layers',16)}<span>Journey explorer</span>${i('chevron-right',14)}</button></nav><div class="side-bottom"><div class="side-note">Treadspace +1 · Interactive P0 prototype<br>Training evidence → meaningful work → validated progression</div><div class="side-person">${avatar(state.role)}<div class="person-text"><div class="who">${role.person}</div><div class="role">${role.title}</div></div></div></div></aside>`;}
  function topbar(){return `<header class="topbar"><div class="crumbs"><span>${D.roles[state.role].label} Experience</span>${i('chevron-right',12)}<b>Treadspace +1</b>${i('chevron-right',12)}<span>${esc(sectionName())}</span>${i('chevron-right',12)}<b>Day ${state.day}</b></div><div class="top-tools"><button class="icon-button mobile-menu" data-action="mobile" aria-label="Open menu">${i('menu',18)}</button><div class="role-switch" aria-label="View as different roles">${['employee','manager','buddy'].map(r=>`<button data-action="role" data-id="${r}" class="${state.role===r?'selected':''}" title="Switch to ${D.roles[r].label} Day ${state.day}">${i(r==='employee'?'briefcase':r==='manager'?'layout-dashboard':'headphones',14)}${D.roles[r].label}</button>`).join('')}</div><button class="icon-button" title="Journey explorer" data-action="explorer">${i('layers',18)}</button><button class="icon-button" title="Notifications and pending actions" data-action="notifications">${i('bell',18)}<span class="noti-dot"></span></button><button class="top-avatar" data-action="profile">${D.roles[state.role].initials}</button></div></header>`;}
  function roleContext(){const d=D.roles[state.role];const extra=state.role==='employee'?`SDE-2 · AI Deployment Engineer · Manager: Aditi Rao · Buddy: Karan Mehta`:state.role==='manager'?'Team members: 8 · New joiners: 2 · Ramp reviews: 2 pending':'Support requests: 2 · Open follow-ups: 1';return `<div class="role-context"><div class="role-id"><div class="avatar ${state.role==='buddy'?'buddy':''}">${d.initials}</div><div><div class="name">${d.person} <span class="tiny muted">· ${d.title}</span></div><div class="sub">${extra}</div></div></div><div class="role-stats">${pill('● '+(state.role==='employee'?'Onboarding active':state.role==='manager'?'Manager mode':'Buddy mode'),'green')}${pill(`Day ${state.day} of 120`,'indigo')}</div></div>`;}
  function timeline(){const approximate={1:3,2:6,5:12,14:20,30:39,31:42,60:65,90:83,120:100};return `<section class="panel journey-card"><div class="journey-top"><div><div class="journey-heading">Your 120-day professional journey <span class="small muted" style="font-weight:500">· same timeline for all three roles</span></div><div class="journey-sub">Hiring intelligence → learning and doing → reviewed work → gradually increasing responsibility</div></div><div class="journey-progress"><span>${approximate[state.day]}% · Day ${state.day}</span><div class="progress-track"><div class="progress-fill" style="width:${approximate[state.day]}%"></div></div></div></div><div class="timeline">${D.stages.map(s=>`<button class="step ${s.day<state.day?'done':''} ${s.day===state.day?'active':''}" data-action="day" data-id="${s.day}" title="Day ${s.day}: ${s.name}"><span class="step-circle">${s.day<state.day?i('check',13):s.day===state.day?'●':D.stages.indexOf(s)+1}</span><div class="step-name">Day ${s.day}</div><div class="step-label">${esc(s.name)}</div></button>`).join('')}</div><div class="date-tabs">${D.days.map(day=>`<button class="date-tab ${state.day===day?'active':''}" data-action="day" data-id="${day}" aria-label="Navigate to Day ${day}">Day ${day}${day===31?'<span class="badgedot"></span>':''}</button>`).join('')}</div></section>`;}
  function profileBanner(message,tag='',tagVariant='green'){return `<section class="panel profile-banner"><div class="summary-profile">${avatar('employee',true)}<div><div class="profile-name">Ranvijay Singh</div><div class="profile-title">SDE-2 · AI Deployment Engineer</div>${pill(tag||'Adaptive ramp active',tagVariant)}</div></div><div class="ai-summary"><strong>${i('sparkles',17)} AI-assisted summary</strong>${esc(message)}<div class="tiny muted" style="margin-top:6px">Illustrative synthesis · review evidence before acting</div></div></section>`;}
  function resourceRows(ids,limit=99){return ids.slice(0,limit).map(id=>{const r=resourceById(id);if(!r)return '';return `<div class="resource-row"><div class="resource-icon">${i(r.type==='Video'?'play':r.type==='Policy'?'shield':r.type==='Workshop'?'graduation':'book-open',16)}</div><div class="resource-body"><div class="resource-name">${esc(r.title)}</div><div class="resource-meta">${esc(r.type)} · ${r.minutes} min${state.resourceDone[id]?' · Completed':''}</div></div>${button(i('external',14),'resource',id,'sm')}</div>`;}).join('');}
  function competencyTable(variant='general'){
    const isSuccess=state.day===31&&state.scenario==='success';
    const shown=D.competencies.map(c=>({...c,current:c.current+(state.day>=31?(isSuccess&&['ML / LLM deployment','Observability & monitoring','Kubernetes','System design & reliability'].includes(c.name)?c.name==='Kubernetes'?0.0:0.5:state.scenario==='support'&&['ML / LLM deployment','Kubernetes','Observability & monitoring','System design & reliability'].includes(c.name)?-.7:0):state.day<14?-.45:state.day<30?-.25:0)}));
    return `<div style="overflow-x:auto"><table class="cmp-table"><thead><tr><th>Competency / Tech stack</th><th>Current level</th><th>Role target</th><th>Gap / status</th></tr></thead><tbody>${shown.map(c=>{const current=Math.max(1,Math.min(5,c.current));const diff=current-c.required;const cls=diff>=0?'strong':diff>=-.6?'developing':'gap';return `<tr><td><button class="btn ghost sm cmp-name" data-action="competency" data-id="${esc(c.name)}" style="padding-left:0;text-align:left">${esc(c.name)} ${i('external',11)}</button></td><td class="bar-cell"><div class="bar-line"><div class="progress-track"><div class="progress-fill" style="width:${current/5*100}%"></div></div><span class="bar-num">${current.toFixed(1)}/5</span></div></td><td class="bar-cell required"><div class="bar-line"><div class="progress-track"><div class="progress-fill" style="width:${c.required/5*100}%"></div></div><span class="bar-num">${c.required.toFixed(1)}/5</span></div></td><td><span class="status-txt ${cls}">${diff>=0?'✓ Meets target':diff>=-.6?'≈ Near match':`△ Gap (${diff.toFixed(1)})`}</span></td></tr>`;}).join('')}</tbody></table></div><div class="tiny muted" style="margin-top:10px">Levels are illustrative hypotheses, not automated performance verdicts. Manager validation and source evidence are required before profile changes are authoritative.</div>`;
  }
  function taskGroups(day){const tasks=D.tasks.filter(t=>t.day===day);const groups=[...new Set(tasks.map(t=>t.category))];return groups.map(group=>{const subset=tasks.filter(t=>t.category===group);const done=subset.filter(t=>state.checks[t.id]).length;return `<div class="task-group"><div class="task-group-title"><span>${esc(group)}</span><span class="tiny muted">${done} / ${subset.length} completed</span></div>${subset.map(t=>`<div class="task-row"><div class="task-left"><button class="check-hit ${state.checks[t.id]?'checked':''}" data-action="check" data-id="${t.id}" title="${state.checks[t.id]?'Reopen':'Mark complete'}: ${esc(t.title)}">${state.checks[t.id]?i('check',13):''}</button><div class="task-copy"><div class="task-title">${esc(t.title)}</div><div class="task-detail">${esc(t.description)} <span class="task-duration">· ${esc(t.duration)}</span></div></div></div><div class="task-actions">${button('Open '+i('external',11),'task',t.id,'sm')}</div></div>`).join('')}</div>`;}).join('');}
  function employeeRail(){const recs=state.day<=2?['company','architecture','security']:state.day<=14?['architecture','repository','observability']:state.day<=31?['reliability','observability','staging']:['incident','design','observability'];return `<div class="stack">${roleInbox()}${card(`${i('sparkles',17)} AI eBuddy`, `<div class="rail-callout">${esc(state.day===1?'Welcome, Ranvijay! Today is about settling in, knowing your people, and getting oriented.':state.day===31&&state.scenario==='support'?'A review can reveal a gap without defining your ability. I can help unpack the retry issue and find approved learning.':state.day>=60?'You are progressing toward independent ownership. I can help with runbooks, incident scenarios, and preparing review evidence.':'Your work and learning are connected. Ask about your current task, relevant resources or what happens next.')}</div><div class="btn-grid" style="margin-bottom:10px">${button('Explain my current task','quick-question','Explain my current task','sm')}${button('Why this learning?','quick-question','Why was this learning recommended?','sm')}${button('What unlocks next?','quick-question','What unlocks my next milestone?','sm')}</div>${chatPreview()}<div class="tiny muted" style="margin-top:8px">Simulated assistant. Not connected to an AI model or company tools.</div>`)}${card('Why this journey is tailored to you',`<p class="section-text">Hiring evidence provides an initial working hypothesis, while actual reviewed work and organisational role requirements shape later recommendations.</p><div class="rail-callout">${esc(D.stages.find(s=>s.day===state.day)?.tag)} · Prior evidence and role-specific requirements determine the proposed next step.</div>${button('View competency mapping','section','competencies','wide')}`)}${card('Your support team',`<div class="stack" style="gap:10px"><div class="role-id">${avatar('manager')}<div><b>Aditi Rao</b><div class="tiny muted">Engineering manager · final work approvals</div></div></div><div class="role-id">${avatar('buddy')}<div><b>Karan Mehta</b><div class="tiny muted">Human buddy · practical peer support</div></div></div><div class="buddy-visibility">Private eBuddy chats stay private by default. The human buddy receives specific requests and authorised task context, not your complete competency profile.</div>${button('Request human help','help','buddy','wide')}${button('See buddy’s view for Day '+state.day,'role','buddy','wide soft')}</div>`)}${card('Suggested learning',`${resourceRows(recs,3)}<div style="margin-top:11px">${button('Explore learning library','section','learning','wide')}</div>`)}</div>`;}
  function chatPreview(){const chat=state.buddyChat.slice(-2);return `${chat.length?`<div class="chat-box" style="min-height:70px">${chat.map(m=>`<div class="chat-line ${m.by==='You'?'user':''}"><div class="chat-by">${esc(m.by)}</div>${esc(m.text)}</div>`).join('')}</div>`:''}<form class="chat-composer" data-form="chat"><input name="message" autocomplete="off" aria-label="Ask eBuddy a question" placeholder="Ask eBuddy anything..." required/><button class="btn primary sm" type="submit" title="Send question">${i('send',15)}</button></form>`;}
  function employeeMain(){
    const c=D.employeeDays[state.day],d=state.day,done=D.tasks.filter(t=>t.day===d&&state.checks[t.id]).length,total=D.tasks.filter(t=>t.day===d).length;
    let main='';
    if(d===1){main=`${card('Your Day 1 essentials',`<div class="insight-banner"><b>Start here.</b> ${esc(c.callout)}</div>${taskGroups(d)}<div class="insight-banner success">${i('check-circle',16)} Belonging begins today. Completing formalities unlocks the Week 1 setup, not a proficiency score.</div>`)}<div class="grid cols-2" style="margin-top:13px">${card('Today’s outcome',`${row('Joining and policy obligations understood','No competency score from administrative tasks')}${row('Access requests confirmed','IT and HR retain access approval')}${row('Introductions complete','Your manager and buddy are available')}`)}${card('What opens next?',`<p class="section-text">${esc(c.next)}</p>${button('Preview Day 2 '+i('arrow-right',14),'day',2,'primary')}`)}</div>`;}
    else if(d===31){main=employeeDay31();}
    else if(d===30){main=`${card('Your first contribution · approved engineering work',`<div class="insight-banner"><b>${state.approvals.day30?'Scope approved by Aditi':'Manager approval pending'}:</b> Improve inference-service reliability in staging with structured logging and retry handling. ${state.approvals.day30?'Approved within the existing engineering workflow.':'Proposed task; Aditi must approve before actual assignment.'}</div><div class="mini-feature"><div class="mini-title">${i('code',17)} Reliability ticket · ENG-218 (illustrative)</div><div class="mini-desc">Acceptance: safely bounded retries, structured error logs, regression tests, staging evidence, reviewed pull request and rollback awareness.</div><div class="btn-grid" style="margin-top:11px">${button('View complete ticket brief','ticket','day30','primary')}${button('View linked work evidence','evidence','day30')}${button('Ask eBuddy about ticket','quick-question','How should I approach the Day 30 ticket?')}</div></div>${taskGroups(d)}<div class="grid cols-2">${card('What you have demonstrated',`${row('Navigated the real codebase','Beyond a sandbox exercise')}${row('Implemented a bounded change','Within approved scope')}${row('Explained the work and limitations','Evidence will go to normal review')}`)}${card('The next opportunity',`<p class="section-text">When Aditi validates the review evidence, the system recommends either a larger scoped task or a focused support cycle.</p>${button('See Day 31 decisions','day',31,'primary')}`)}</div>`)} `;}
    else if(d===14){main=`${card('A reviewed exercise · learning through work',`<div class="insight-banner"><b>Your current challenge:</b> ${esc(c.callout)}</div><div class="grid cols-2">${feature('01 · LEARN','Understand the existing stack','Targeted model-serving patterns and approved company walkthrough.','architecture')}${feature('02 · DO','Build and run the service','Containerise, run tests, record logs and submit the branch.','repository')}${feature('03 · LEARN AGAIN','Use review evidence','Reviewer flagged weak p95 latency instrumentation.','observability')}${feature('04 · DO BETTER','Improve and resubmit','Add metrics, record latency evidence and return for review.','observability')}</div>${taskGroups(d)}<div class="insight-banner"><b>Why did the plan adapt?</b> A reviewed practice task exposed a specific observability gap. eBuddy recommends one approved resource and a focused revision instead of unrelated coursework.<div class="btn-grid" style="margin-top:11px">${button('Open learning + review feedback','learning-drawer','observability')}${button('Inspect code-review evidence','evidence','day14')}</div></div><div class="grid cols-2">${card('Evidence behind this milestone',`${row('Containerised endpoint completed','Functional checks passed')}${row('Latency monitoring revision required','Reviewer request remains actionable','alert-triangle')}${row('Manager / engineer review pending','No automatic sign-off')}`)}${card('What comes after review?',`<p class="section-text">${esc(c.next)}</p>${button('Preview Day 30','day',30,'primary')}`)}</div>`)} `;}
    else if(d===60){main=`${card('Scoped ownership · reliability improvement',`<div class="insight-banner"><b>A larger responsibility, not another batch of videos.</b> ${esc(c.callout)}</div><div class="grid cols-2">${feature('WORKSTREAM','Reliability improvements','Own service-health checks, observability and rollback documentation.','incident')}${feature('WORK-LINKED LEARNING','Targeted resources, only when useful','Approved case studies and playbooks accompany the work, not replace it.','observability')}</div>${taskGroups(d)}<div class="stat-strip"><div class="stat"><div class="stat-num">3</div><div class="stat-label">Reviewed engineering contributions · demo</div></div><div class="stat"><div class="stat-num">2</div><div class="stat-label">Validated role milestones · demo</div></div><div class="stat"><div class="stat-num">1</div><div class="stat-label">Scoped component under ownership</div></div></div><div class="insight-banner success"><b>Next unlock: Day 90 delivery and impact.</b> After manager review, progress toward a broader end-to-end deliverable while maintaining normal code review and release controls.</div>`)} `;}
    else{main=`${card(d===2?'Learn → Apply → Discuss':d===5?'Learn, do, review':'Work-linked milestone',`<div class="insight-banner"><b>Your current focus:</b> ${esc(c.callout)}</div>${d===5?`<div class="mini-feature tinted"><div class="mini-title">${i('code',17)} Starter assignment · AI inference sandbox</div><div class="mini-desc">Build a small model-serving API using the team’s approved template. Trace the request from gateway to model artifact and logs. No production credentials required.</div><div class="btn-grid" style="margin-top:10px">${button('Open task brief','task','sandbox','primary')}${button('Open codebase guide','resource','repository')}${button('Submit work evidence','submit-evidence','sandbox')}</div></div>`:''}${taskGroups(d)}<div class="grid cols-2" style="margin-top:13px">${card('Evidence and learning outcome',`${row(c.result,'Reviewed evidence matters more than course completion')}${button('Inspect milestone evidence','evidence','milestone','sm')}`)}${card('What comes next?',`<p class="section-text">${esc(c.next)}</p>${button('Continue journey '+i('arrow-right',14),'day',D.days[Math.min(D.days.indexOf(d)+1,D.days.length-1)],'primary')}`)}</div>`)} `;}
    const status=d===31?scenarioToggle():pill(`${done}/${total} actions reviewed`,'indigo');
    return `<div class="page-head"><div><div class="eyebrow">${esc(c.kicker)}</div><h1 class="page-title">Day ${d}: ${esc(c.title)}</h1><p class="page-desc">${esc(c.description)}</p></div><div class="head-actions">${status}${button('View all perspectives','explorer','','soft')}</div></div>${timeline()}<div class="content-with-rail"><div class="stack">${main}</div>${employeeRail()}</div>`;
  }
  function feature(label,title,desc,res){return `<div class="mini-feature tinted"><div class="quick-label">${esc(label)}</div><div class="mini-title" style="margin-top:8px">${esc(title)}</div><div class="mini-desc">${esc(desc)}</div><div style="margin-top:12px">${button('Open guidance','resource',res,'sm')}</div></div>`;}
  function employeeDay31(){const success=state.scenario==='success';return `${profileBanner(success?'The Day 30 reliability ticket passed review. Structured logs, bounded retries and staging checks support a broader next assignment.':'The Day 30 reliability ticket was partly completed. Initial code and local tests succeeded, while retry handling and staging validation require a focused recovery plan.',success?'Ticket completed successfully':'Support after Day 30 task',success?'green':'amber')}<div class="grid cols-2">${card(success?'Completed · reviewed contribution':'What you achieved so far',`<div class="insight-banner ${success?'success':''}">${success?'Structured logging, retry handling and staging validation completed; review feedback addressed.':'Repository setup, branch creation, partial logging, successful local tests and initial documentation are useful progress.'}</div>${row('Evidence is attached','Code review, tests and staging records')}${row('Manager judgement remains final','No inferred score is treated as a promotion decision')}${button('View evidence','evidence','day31','wide')}`)}${card(success?'Your next opportunity':'Where you got stuck',success?`${row('Step into broader ownership','More meaningful work, proportionate to demonstrated readiness')}${row('Keep learning on demand','Support remains available when needed')}${button('Preview Day 60','day',60,'primary wide')}`:`${row('Retry handling end to end','Review failure modes and bounded retry strategy','alert-triangle')}${row('Staging validation','Use approved rollout checklist','alert-triangle')}${row('Interpreting failure logs','Find the likely root cause','alert-triangle')}${button('Request a coaching session','help','buddy','primary wide')}`)}</div>${card('Live competency map · source evidence required',competencyTable())}${card(success?'Recommended next path · more meaningful work':'Recommended recovery path',success?`<div class="choice-grid">${nextTicketCards()}</div><div class="btn-grid" style="margin-top:12px">${button('Ask manager to approve a next ticket','message-manager','next-ticket','primary')}${button('Review role expectations','section','competencies')}</div>`:`<div class="ordered">${[['Targeted coaching','Review retry handling, staging validation and logs.'],['Guided practice','Complete one small retry fix with Karan’s support.'],['Buddy-assisted retry','Let Ranvijay lead the changes and tests.'],['Manager re-review','Reassess the new evidence rather than the original failure.']].map((a,j)=>`<div class="ordered-item"><span class="number-circle">${j+1}</span><div><b>${a[0]}</b><div class="small muted">${a[1]}</div></div></div>`).join('')}</div><div class="btn-grid" style="margin-top:12px">${button('Open recovery learning','resource','reliability','primary')}${button('Switch to Karan’s support view','role','buddy')}</div>`)}${card('Day 31 follow-up tasks',taskGroups(31))}`;}
  function nextTicketCards(){const choices=[['option-1','Own a larger inference-service improvement','Build on structured logging, deployment validation and service quality.','3–5 days · Low risk'],['option-2','Add monitoring and alerting to the service','Extend observability and operational ownership.','2–4 days · Low–medium risk'],['option-3','Take a bounded reliability backlog item','Extend reliability practices within approved limits.','2–4 days · Medium risk']];return choices.map(([id,title,desc,meta],j)=>`<button class="choice ${state.selectedTicket===id?'selected':''}" data-action="select-ticket" data-id="${id}"><span class="choice-number">Option ${j+1}${state.selectedTicket===id?' · Selected':''}</span><div class="choice-title">${title}</div><div class="mini-desc">${desc}</div><div class="choice-meta">${meta}</div></button>`).join('');}
  function mgrProfileAndHead(){let d=state.day,c=D.managerDays[d];return `<div class="page-head"><div><div class="eyebrow">Manager workspace · Day ${d}</div><h1 class="page-title">${esc(c.title)}</h1><p class="page-desc">${esc(c.subtitle)}</p></div><div class="head-actions">${d===31?scenarioToggle():pill('Manager review','indigo')}${button('View employee experience','role','employee','soft')}</div></div>${timeline()}`;}
  function scenarioToggle(){return `<div class="scenario-toggle" aria-label="Demo outcome scenario"><button class="${state.scenario==='success'?'active':''}" data-action="scenario" data-id="success">${i('check-circle',13)} Completed</button><button class="${state.scenario==='support'?'active':''}" data-action="scenario" data-id="support">${i('life-buoy',13)} Needs support</button></div>`;}
  function managerMain(){let d=state.day,c=D.managerDays[d];let core=d===30?managerDay30():d===31?managerDay31():managerGeneric();return mgrProfileAndHead()+core;}
  function managerGeneric(){let d=state.day,c=D.managerDays[d];return `${profileBanner(`Ranvijay’s Day ${d} manager checkpoint prioritises ${c.focus.toLowerCase()}. Suggestions are based on hiring context, the role plan and illustrative review evidence.`,'Manager checkpoint','indigo')}<div class="wide-content-with-rail"><div class="stack"><div class="grid cols-2">${card(`${i('target',17)} What this review should establish`,`<div class="insight-banner"><b>Primary objective:</b> ${esc(c.focus)}</div>${c.actions.map((s,j)=>`<div class="list-check">${i('check-circle',16)}<div><b>${esc(s)}</b><p>Click for suggested decision criteria and next action</p></div>${button('Review','manager-action',`${d}:${j}`,'sm')}</div>`).join('')}`)}${card(`${i('file',17)} Available evidence`,`<p class="section-text">Review evidence before accepting AI recommendations or modifying the competency profile.</p>${c.evidence.map(e=>row(e,'Illustrative / awaiting human validation')).join('<div style="height:10px"></div>')}${button('Inspect evidence drawer','evidence',`manager-${d}`,'wide')}`)}</div>${card('Competency-to-role fit · manager view',competencyTable())}${card('Decision notes and next-step ownership',`<div class="insight-banner">Manager sign-off remains required for task scope, progression and any official proficiency update. The buddy supports learning, not a shadow performance assessment.</div><div class="btn-grid">${button('Add manager note','note','manager','primary')}${button('Schedule milestone review','schedule','review')}${button('View human buddy briefing','role','buddy')}</div>`)}</div><aside class="stack">${roleInbox()}${card('Recommended manager actions',`<div class="ordered">${c.actions.map((s,j)=>`<div class="ordered-item"><span class="number-circle">${j+1}</span><div><b>${esc(s)}</b></div></div>`).join('')}</div><div style="margin-top:12px">${button('Record action / decision','note','manager','primary wide')}</div>`)}${card('Suggested resources',resourceRows(c.resources))}${card('What this unlocks',`<div class="insight-banner success">${esc(D.employeeDays[d].next)}</div>${button('Preview next checkpoint','day',D.days[Math.min(D.days.indexOf(d)+1,D.days.length-1)],'wide')}`)}</aside></div>`;}
  function managerDay30(){return `${profileBanner('The proposed staging-reliability ticket uses Ranvijay’s Python strengths while stretching his ML deployment and observability practice. All task allocation and release controls require manager approval.','Ready for manager review','green')}<div class="wide-content-with-rail"><div class="stack"><div class="grid cols-2">${card(`${i('sparkles',17)} AI-suggested real engineering ticket`,`<div class="insight-banner"><b>Improve inference service reliability in staging by adding structured logging and retry handling.</b></div><div class="mini-title">Why this ticket?</div>${row('Leverages Python and backend foundations','Existing service design and unit testing')}${row('Develops reliability and observability','Safe, low-risk scope tied to the role')}${button('Inspect ticket and evidence','ticket','day30','wide')}`)}${card(`${i('check-circle',17)} Ticket approval parameters`,`<p class="section-text">The manager confirms acceptance criteria, risk and reviewer ownership before assignment.</p>${[['Acceptance criteria','5 / 5'],['Code quality and test plan','4 / 5'],['System understanding','4 / 5'],['Safe deployment behaviour','5 / 5'],['Debugging and monitoring','4 / 5'],['Documentation and communication','4 / 5']].map(([s,v])=>`<div class="task-row" style="padding:7px 2px">${i('check-circle',15)}<b class="small" style="flex:1">${s}</b>${pill(v,'green')}</div>`).join('')}<div class="insight-banner success">${state.approvals.day30?'✓ Approved by Aditi. The employee can see the assigned scope.':'Awaiting manager approval. AI cannot assign this ticket by itself.'}</div>`)}</div>${card('Real-time competency evidence vs role requirements',competencyTable())}${card('Where Ranvijay stands today',`<div class="grid cols-3">${feature('Strengths','Python & CI/CD','Good coding fundamentals, test routines and code quality.','repository')}${feature('Near-match','Cloud and observability','Some exposure, yet delivery evidence is still developing.','observability')}${feature('Growth area','Kubernetes & reliability','Build deeper operational understanding through reviewed work.','kubernetes')}</div>`)}</div><aside class="stack">${roleInbox()}${card('Manager decision',`<div class="ai-summary"><strong>${i('sparkles',16)} AI recommendation</strong>Approve this bounded, low-risk ticket if the proposed scope matches the live engineering backlog and release policy.</div><div class="insight-banner ${state.approvals.day30?'success':''}">${state.approvals.day30?'Ticket approved for this demo.':'Manager approval not yet recorded.'}</div><div class="btn-grid" style="flex-direction:column">${button(state.approvals.day30?'View approval record':'Approve suggested ticket','approve-ticket','day30','primary wide')}${button('Revise ticket scope','revise-ticket','day30','wide')}${button('Add manager note','note','manager','wide')}${button('Plan next milestone','schedule','review','wide')}</div>`)}${card('What approval unlocks',`${row('Reviewed, meaningful work','Ticket assigned under standard engineering controls')}${row('Day 31 outcome review','Evidence from PR, tests and deployment')}${button('See Day 31','day',31,'wide')}`)}</aside></div>`;}
  function managerDay31(){let ok=state.scenario==='success';return `${profileBanner(ok?'Ranvijay delivered the ticket, addressed review comments and showed improved understanding of deployment reliability, staging validation and safe retries.':'Ranvijay made partial progress: branch setup, structured logging and local tests. Retry handling, staging validation and interpreting failure logs remain blockers.',ok?'Ticket completed successfully':'Needs support after Day 30 task',ok?'green':'amber')}<div class="wide-content-with-rail"><div class="stack">${ok?managerDay31Success():managerDay31Support()}</div><aside class="stack">${roleInbox()}${ok?card('Recommended manager actions',`${row('Approve the next scoped ticket','Broader work grounded in reviewed evidence')}${row('Increase responsibility gradually','Keep risk limits and acceptance criteria explicit')}${row('Keep buddy available','Useful, but not mandatory')}${row('Schedule Week 5 checkpoint','Assess next outcomes')}${button('Assign selected next ticket','assign-next','next','primary wide')}${button('Plan Week 5 milestone','schedule','week5','wide')}${button('Add manager note','note','manager','wide')}`):card('Human buddy support',`<div class="role-id" style="margin:10px 0">${avatar('buddy')}<div><b>Karan Mehta</b><div class="tiny muted">Staff Engineer / Human Buddy</div></div></div><div class="ai-summary"><strong>${i('sparkles',15)} AI-drafted buddy brief</strong>Task: reliability ticket. Where he got stuck: bounded retry logic, staging validation and failure logs. Suggested help: guided debugging followed by an independent next attempt.</div><div class="btn-grid" style="margin-top:11px;flex-direction:column">${button('Tag Karan with AI brief','tag-buddy','day31','primary wide')}${button('Add manager note','note','manager','wide')}${button('Schedule review after support','schedule','review','wide')}${button('Open buddy’s Day 31 page','role','buddy','wide')}</div>`)}${card('Suggested learning already shared',resourceRows(ok?['incident','observability','design']:['kubernetes','observability','reliability','staging']))}${card('Next-step checkpoint',`<div class="insight-banner ${ok?'success':'warn'}"><b>${ok?'Growth trajectory':'Recovery trajectory'}:</b> ${ok?'Broaden autonomy with clear limits and peer review.':'Support a focused retry, then reassess actual work evidence.'}</div>${button('Switch outcome scenario','scenario',ok?'support':'success','wide')}`)}</aside></div>`;}
  function managerDay31Success(){return `<div class="grid cols-2">${card('AI outcome report · milestone achieved',`${row('Completed contribution','Logging, retries, staging validation and reviewed PR notes')}${row('Evidence reviewed','PR quality, tests, staging behaviour and reviewer feedback')}${row('Why it matters','Applied operational practices in a service workflow')}${button('Open reviewed work','evidence','day31','wide')}`)}${card('What changed after this ticket',`<div class="mini-feature tinted">${row('Strengthened areas','Deployment confidence, staging habits, log literacy')}</div><div class="mini-feature tinted" style="margin-top:8px">${row('Still developing','Advanced Kubernetes and system design')}</div><div class="mini-feature tinted" style="margin-top:8px">${row('Confidence gained','More ownership after reviewed delivery')}</div>`)}</div>${card('Updated competency and proficiency · demonstration',competencyTable())}${card('AI recommendation · move toward meaningful work',`<p class="section-text">Based on the reviewed ticket, draft next-scoped-work suggestions for Aditi’s approval.</p><div class="choice-grid">${nextTicketCards()}</div><div style="margin-top:12px">${button('Assign selected task','assign-next','next','primary')}${button('Explain recommendation','evidence','recommendation')}</div>`)}`;}
  function managerDay31Support(){return `<div class="grid cols-2">${card('What he did vs could not complete',`<div class="insight-banner success"><b>Completed / attempted</b>${['Set up branch and base changes','Added partial structured logging','Ran local tests successfully','Documented initial approach'].map(t=>row(t,'')).join('')}</div><div class="insight-banner warn"><b>Not completed</b>${['Retry handling end-to-end','Staging validation','Interpreting failure logs','Final reviewed PR closure'].map(t=>`<div style="margin:6px 0">${i('alert-triangle',13)} ${t}</div>`).join('')}</div>`)}${card('AI interpretation of likely gaps',`<div class="insight-banner"><b>Assumed technical gaps</b><div class="small">Kubernetes service behaviour; deployment troubleshooting; observability interpretation; confidence in staging.</div></div><div class="insight-banner"><b>Possible work-pattern gaps</b><div class="small">Uncertainty under ambiguity, escalation timing and translating feedback into another iteration.</div></div><div class="insight-banner success"><b>Confidence note:</b> Strong Python fundamentals, code structure and documentation remain visible.</div><div class="tiny muted">These are hypotheses for a human to validate, not diagnoses of the employee.</div>`)} </div>${card('Real-time competency and proficiency vs role requirement',competencyTable())}<div class="grid cols-2">${card('How Aditi can guide Ranvijay',`${['Hold a short, supportive debrief','Ask him to explain his thought process','Clarify expectations for retry, logs and staging','Offer a smaller recovery task after coaching','Treat the first attempt as a learning milestone'].map(s=>row(s,'')).join('<div style="height:7px"></div>')}`)}${card('Recommended next path',`<div class="ordered">${[['Targeted coaching','Short focused session on blockers'],['Guided practice','A scoped failure-mode exercise'],['Buddy-assisted retry','Let him drive and receive feedback'],['Manager re-review','Decide from new evidence']].map((x,j)=>`<div class="ordered-item"><span class="number-circle">${j+1}</span><div><b>${x[0]}</b><div class="small muted">${x[1]}</div></div></div>`).join('')}</div><div style="margin-top:12px">${button('Initiate buddy intervention','tag-buddy','day31','primary wide')}</div>`)}</div>`;}
  function buddyMain(){const d=state.day,c=D.buddyDays[d];let support=d===31&&state.scenario==='support';return `<div class="page-head"><div><div class="eyebrow">Human buddy workspace · Day ${d}</div><h1 class="page-title">${esc(c.title)}</h1><p class="page-desc">${esc(c.subtitle)}</p></div><div class="head-actions">${d===31?scenarioToggle():pill('Buddy support','green')}${button('See manager’s view','role','manager','soft')}</div></div>${timeline()}${support?buddyDay31Support():buddyGeneric()}`;}
  function buddyGeneric(){let d=state.day,c=D.buddyDays[d];return `${profileBanner(`Karan is the designated human buddy for Ranvijay’s Day ${d} milestone. His role is practical, humane peer support. He cannot unilaterally assign tasks or modify formal competency judgements.`,'Buddy available','green')}<div class="wide-content-with-rail"><div class="stack"><div class="grid cols-2">${card('What Karan can help with',`<div class="insight-banner"><b>Focus:</b> ${esc(c.focus)}</div>${c.actions.map((s,j)=>`<div class="list-check">${i('check-circle',16)}<div style="flex:1"><b>${esc(s)}</b></div>${button('Coach','coach',`${d}:${j}`,'sm')}</div>`).join('')}`)}${card('How to counsel and guide Ranvijay',`<p class="section-text">Practical coaching cues adapted to the stage of his ramp.</p><div class="ordered">${c.tips.map((s,j)=>`<div class="ordered-item"><span class="number-circle">0${j+1}</span><div><b>${esc(s)}</b><div class="small muted">Ask before explaining; let Ranvijay retain ownership.</div></div></div>`).join('')}</div><div style="margin-top:12px">${button('Open coaching notes','note','buddy','wide')}</div>`)}</div>${card('Learning cues you can recommend',`<p class="section-text">Only organisation-approved resources. Share the relevant item, not a generic course dump.</p>${resourceRows(c.resources)}<div style="margin-top:11px">${button('View all resource suggestions','section','learning','wide')}</div>`)}${card('AI-drafted human buddy message',`<div class="ai-summary">${esc(`Hi Ranvijay, I’m Karan. For our Day ${d} checkpoint, I can help you with ${c.focus.toLowerCase()}. We can spend 20 minutes on what you’ve tried and identify a practical next step.`)}</div><div class="btn-grid" style="margin-top:10px">${button('Review / edit / send','draft-message','buddy','primary')}${button('Send note to Aditi','message-manager','buddy')}</div>`)} </div><aside class="stack">${roleInbox()}${buddyPermissions()}${card('Your next actions',`<div class="ordered">${c.actions.slice(0,4).map((s,j)=>`<div class="ordered-item"><span class="number-circle">${j+1}</span><b>${esc(s)}</b></div>`).join('')}</div><div class="btn-grid" style="margin-top:12px;flex-direction:column">${button('Record coaching outcome','note','buddy','primary wide')}${button('Schedule short pairing session','schedule','buddy','wide')}${button('Escalate a blocker to Aditi','escalate','buddy','wide')}</div>`)}${card('After the coaching session',`${row('Share factual progress','Avoid private conversations or unsupported judgements')}${row('Keep approvals with Aditi','Buddy is not a parallel manager')}${button('Mark buddy support complete','complete-support','buddy','green wide')}`)}</aside></div>`;}
  function buddyPermissions(){return card(`${i('eye',17)} What you can see`,`<div class="compact-list">${row('Task context','The relevant scoped work and learning intent')}${row('Manager’s support request','Selected blockers and an authorised brief')}${row('Recommended coaching cues','Guidance and approved resources')}</div><div class="buddy-visibility" style="margin-top:12px">${i('lock',14)} Not visible: private HR records, compensation, complete performance evaluations or private eBuddy chat history.</div>`);}
  function roleInbox(){const person=D.roles[state.role].person;const related=state.messages.filter(m=>m.to===person).slice(0,4);const shared=state.notes.filter(n=>n.visibility==='shared'&&n.role!==state.role&&(state.role==='manager'||state.role==='employee')).slice(0,3);return card(`${i('message',17)} Shared updates and requests`,`${related.length||shared.length?`${related.map(m=>`<div class="record-item"><div class="record-date">${esc(m.when)} · from ${esc(m.role)}</div><b>${esc(m.subject)}</b><div>${esc(m.body)}</div></div>`).join('')}${shared.map(n=>`<div class="record-item"><div class="record-date">${esc(n.when)} · shared by ${esc(n.role)}</div><b>${esc(n.subject)}</b><div>${esc(n.body)}</div></div>`).join('')}`:'<div class="empty" style="padding:17px">No shared updates yet. Send a support request or manager note to see it appear in the corresponding role.</div>'}${button('Review recent activity','notifications','','wide')}`);}
  function buddyDay31Support(){return `${profileBanner('Aditi requested Karan’s help after partial completion of the Day 30 reliability ticket. Ranvijay has demonstrated useful progress, but needs support to finish retry handling and staging validation.','Needs buddy help','amber')}<div class="wide-content-with-rail"><div class="stack"><div class="grid cols-2">${card(`${i('target',17)} What task was given?`,`<div class="insight-banner"><b>Day 30 ticket:</b> Improve inference service reliability through structured logging and bounded retry handling.</div><div class="mini-title">Why this task was chosen</div><p class="section-text">It builds on Python and backend strengths, exposes an important operational capability and aligns to real team work.</p><div class="mini-title">Intended learning value</div><p class="section-text">Better error diagnosis, safe retry patterns, staging validation and engineering ownership.</p>${button('Open approved ticket brief','ticket','day30','wide')}`)}${card(`${i('chart',17)} What he managed vs where he got stuck`,`<div class="grid cols-2"><div class="mini-feature" style="background:#effaf4"><b style="color:#16774f">✓ He managed</b>${['Branch setup','Basic local build','Partial structured logging','Local tests','Initial notes'].map(x=>`<div class="line-item" style="margin-top:9px">${i('check',13)}${x}</div>`).join('')}</div><div class="mini-feature" style="background:#fff8ec"><b style="color:#996513">△ He got stuck</b>${['Integrating retry logic','Reading the failure logs','Staging validation','Escalation timing'].map(x=>`<div class="line-item warn" style="margin-top:9px">${i('alert-triangle',13)}${x}</div>`).join('')}</div></div>`)}</div><div class="grid cols-2">${card(`${i('sparkles',17)} AI view: likely gaps and how you can help`,`<div class="compact-list">${row('Deployment troubleshooting','Walk through one failing example; let him explain his hypothesis')}${row('Observability interpretation','Ask what the logs show and what evidence is missing')}${row('Confidence under ambiguity','Normalise uncertainty; agree on one small next attempt')}</div><div class="insight-banner warn">These are coaching hypotheses, not a diagnosis or official performance evaluation.</div>`)}${card(`${i('users',17)} How to counsel and guide Ranvijay`,`<div class="ordered">${[['Start with reassurance','Acknowledge real progress; this is one learning episode.'],['Ask how he approached the task','Let him walk you through the work already done.'],['Isolate one blocker','Focus on retry integration, logs or staging.'],['Pair, but let him drive','Co-debug; let Ranvijay write and execute changes.'],['End with one independent action','Agree a small, verifiable next step.']].map((a,j)=>`<div class="ordered-item"><span class="number-circle">0${j+1}</span><div><b>${a[0]}</b><div class="small muted">${a[1]}</div></div></div>`).join('')}</div>`)}</div>${card('AI-drafted buddy message',`<div class="ai-summary"><strong>${i('sparkles',16)} Ready to personalise</strong>Hi Ranvijay, Aditi asked me to help with the Day 30 reliability ticket. Let’s sit together for 20–30 minutes, understand the blocker and work through your next step. We’ll break it down and get you moving again.</div><div class="btn-grid" style="margin-top:11px">${button('Edit and send buddy message','draft-message','day31','primary')}${button('Record a coaching note','note','buddy')}</div>`)}</div><aside class="stack">${roleInbox()}${buddyPermissions()}${card('Resources suggested to Ranvijay',resourceRows(['reliability','staging','kubernetes','observability']))}${card('After the coaching session',`<div class="btn-grid" style="flex-direction:column">${button(state.supportComplete?'✓ Support recorded':'Mark support complete','complete-support','buddy','primary wide')}${button('Send factual note to Aditi','message-manager','buddy','wide')}${button('Request another review','schedule','review','wide')}${button('Recommend a small recovery task','recovery-task','buddy','wide')}${button('Switch to manager view','role','manager','wide')}</div>`)}</aside></div>`;}
  function secondaryHead(){const d=state.day;return `<div class="page-head"><div><div class="eyebrow">${D.roles[state.role].label} workspace · Day ${d}</div><h1 class="page-title">${esc(sectionName())}</h1><p class="page-desc">Explore linked information and perform realistic, simulated P0 actions without leaving the coordinated journey.</p></div><div class="head-actions">${button('Return to Day '+d+' journey','section','journey','primary')}${button('Compare roles','explorer','','soft')}</div></div>${timeline()}`;}
  function learningPage(){let q=(state.filters.resource||'').toLowerCase();let rs=D.resources.filter(r=>[r.title,r.type,r.detail,...r.tags].join(' ').toLowerCase().includes(q));return `<div class="wide-content-with-rail"><div class="stack">${card(`${i('book-open',17)} Approved work-linked learning library`,`<p class="section-text">A curated P0 catalogue. Materials are linked to a role requirement, a task or a reviewer-identified gap. The organisation owns and approves the material.</p><form class="searchbox" data-form="search-resources">${i('search',17)}<input name="query" value="${esc(state.filters.resource||'')}" aria-label="Search resources" placeholder="Search by skill, material or task..."/><button type="submit" class="btn sm">Search</button></form><div class="tiny muted" style="margin:10px 0">${rs.length} resources matching your search</div>${rs.length?rs.map(r=>`<div class="resource-row"><div class="resource-icon">${i(r.type==='Video'?'play':'book-open',19)}</div><div class="resource-body"><div class="resource-name">${esc(r.title)}</div><div class="resource-meta">${esc(r.type)} · ${r.minutes} min · ${r.tags.map(esc).join(' · ')}</div><div class="tiny muted">${esc(r.detail)}</div></div><div class="btn-grid">${button('View','resource',r.id,'sm')}${button(state.resourcePlan[r.id]?'In plan':'Add to plan','resource-plan',r.id,'sm')}</div></div>`).join(''):'<div class="empty">No matching resource in this illustrative library. Try “staging”, “Kubernetes” or “architecture”.</div>'}`)}${card('What P0 does not build',`<div class="insight-banner">Treadspace +1 curates, explains and sequences existing approved organisational material. It does not need a full video-learning platform or proprietary course authoring to prove the closed feedback loop.</div>`)}</div><aside class="stack">${card('Learning recommended for this day',resourceRows(D[state.role==='manager'?'managerDays':state.role==='buddy'?'buddyDays':'managerDays'][state.day].resources||['architecture','observability']))}${card('Adaptive learning logic',`${row('Initial baseline','Hiring evidence and role expectations')}${row('Observed work evidence','Reviewed tasks, not passive consumption')}${row('Gap response','Small targeted resource + retry')}${row('Approval and governance','Source, visibility, and manager validation')}`)}</aside></div>`;}
  function competencyPage(){return `<div class="wide-content-with-rail"><div class="stack">${card('Competency and proficiency map',competencyTable())}${card('How recommendations are derived',`<div class="ordered">${[['Starting baseline','Hiring-stage profile and experience are imported as provisional data.'],['Role requirements','Organisation-approved competencies and target proficiency establish expectations.'],['Work evidence','Tests, reviews, tasks and human feedback may support an update.'],['Human validation','The manager approves significant proficiency changes and next work scope.']].map((x,j)=>`<div class="ordered-item"><span class="number-circle">${j+1}</span><div><b>${x[0]}</b><div class="small muted">${x[1]}</div></div></div>`).join('')}</div>`)} </div><aside class="stack">${card('Current checkpoint',`<div class="insight-banner">Day ${state.day}: ${esc(D.stages.find(s=>s.day===state.day).tag)}</div>${button('Inspect evidence','evidence','milestone','wide')}${button('View manager perspective','role','manager','wide')}`)}${card('Evidence governance',`${row('Source linked','Traceable to a review, task or authorised appraisal')}${row('Provisional by default','No unreviewed AI verdict becomes official')}${row('Restricted access','Human buddy sees only the help they are asked to provide')}`)}</aside></div>`;}
  function tasksPage(){let all=D.tasks.filter(t=>t.day<=state.day);return `<div class="wide-content-with-rail"><div class="stack">${card('Work and task evidence',`<p class="section-text">Practice tasks are separated from manager-approved live engineering work. Tasks remain in the existing source of truth.</p><div class="grid cols-2">${feature('Practice','Evidence-building exercises','Safe environment to test skills and identify learning needs.','repository')}${feature('Live work','Manager-approved tasks','Bounded contribution with normal engineering reviews.','reliability')}</div>${D.days.filter(d=>d<=state.day).map(d=>`<div style="margin:18px 0 6px" class="mini-title">Day ${d} · ${esc(D.stages.find(s=>s.day===d).short)}</div>${D.tasks.filter(t=>t.day===d).map(t=>`<div class="task-row" style="background:#fff;border:1px solid var(--border);border-radius:8px;margin:4px 0"><div class="task-left">${i(state.checks[t.id]?'check-circle':'clock',16)}<div><b class="small">${esc(t.title)}</b><div class="tiny muted">${esc(t.category)}</div></div></div>${button('View','task',t.id,'sm')}</div>`).join('')}`).join('')}`)} </div><aside class="stack">${card('Work integrations · P0',`${row('Jira / Azure DevOps','Link tickets and statuses')}${row('GitHub / source control','Link PR and review evidence')}${row('Deployment/test systems','Point to authorised validation evidence')}<div class="insight-banner">Illustrative links only. No live Jira, GitHub or cloud permissions are requested in this demo.</div>${button('View example ticket','ticket','day30','wide')}`)}${card('Recording evidence',`${button('Submit work evidence','submit-evidence','generic','primary wide')}${button('Add reflection note','note','employee','wide')}`)}</aside></div>`;}
  function milestonePage(){let progress=D.days.indexOf(state.day);return `<div class="stack">${card('Milestones and ownership progression',`<p class="section-text">The employee’s progress reflects stage completion and human-reviewed evidence. XP is optional engagement scaffolding, never a competency score.</p><div class="grid cols-3">${D.stages.map((s,j)=>`<div class="mini-feature ${s.day===state.day?'tinted':''}"><div class="quick-label">${j<progress?'✓ Reached':j===progress?'● Current':'○ Upcoming'} · Day ${s.day}</div><div class="mini-title" style="margin-top:9px">${esc(s.short)}</div><div class="mini-desc">${esc(s.name)}</div><div style="margin-top:12px">${button('Explore all roles','day',s.day,'sm')}</div></div>`).join('')}</div>`)}${card('Progression rules',`${row('Every stage has a purpose','Know, do, review and progress')}${row('Review gates require responsible approval','Hiring evidence does not decide readiness alone')}${row('Support is part of progression','A blocked ticket does not erase strengths')}${row('Autonomy grows gradually','Risk and role requirements still apply')}`)}</div>`;}
  function peoplePage(){return `<div class="wide-content-with-rail"><div class="stack">${card('Your support network',`<div class="grid cols-2"><div class="mini-feature">${avatar('manager',true)}<div class="mini-title" style="margin-top:12px">Aditi Rao</div><div class="mini-desc">Engineering manager. Approves work scope, reviews milestones and validates competency changes.</div><div class="btn-grid" style="margin-top:13px">${button('Message Aditi','message-manager','employee','primary')}${button('View manager journey','role','manager')}</div></div><div class="mini-feature">${avatar('buddy',true)}<div class="mini-title" style="margin-top:12px">Karan Mehta</div><div class="mini-desc">Staff engineer and human buddy. Helps with technical context, team norms, pair-debugging and moral support.</div><div class="btn-grid" style="margin-top:13px">${button('Ask for help','help','buddy','primary')}${button('View buddy journey','role','buddy')}</div></div></div>`)}${card('Privacy boundary',`<div class="insight-banner">The buddy can see the specific task, learning intent and manager-authorised support brief. He does not receive HR records, salary information or full performance assessment history. The employee’s private eBuddy conversation is not shared automatically.</div>`)} </div><aside class="stack">${card('Upcoming touchpoints',`${row('Day 5','First working sandbox review')}${row('Day 14','Iteration and learning feedback')}${row('Day 30/31','First real contribution and decision')}${button('Schedule a check-in','schedule','buddy','wide')}`)}</aside></div>`;}
  function interventionsPage(){return `<div class="wide-content-with-rail"><div class="stack">${card('Support and intervention workbench',`<div class="insight-banner warn"><b>Example active intervention:</b> Ranvijay struggled with retry handling and staging validation after Day 30. The assistance route is optional, narrow and supportive.</div>${row('Trigger','A specific reviewed task encountered blockers')}${row('Manager decision','Aditi decides whether and how support is offered')}${row('Human buddy','Karan receives limited task context and learning cues')}${row('Recovery','Small next attempt, new evidence and re-review')}<div class="btn-grid" style="margin-top:15px">${button('Open Day 31 support case','day',31,'primary')}${button('Tag buddy for support','tag-buddy','day31')}${button('Escalate blocker','escalate','case')}</div>`)}${card('Intervention log',`${state.activities.filter(a=>/buddy|support|review|intervention|escalat|coach/i.test(a.label)).length?state.activities.filter(a=>/buddy|support|review|intervention|escalat|coach/i.test(a.label)).slice(0,10).map(a=>`<div class="record-item"><div class="record-date">${esc(a.time)} · Day ${a.day}</div>${esc(a.label)}</div>`).join(''):'<div class="empty">No intervention recorded yet. The Day 31 case demonstrates how an intervention begins.</div>'}`)}</div><aside>${card('Available actions',`${button('Review buddy permissions','permissions','buddy','wide')}${button('Record manager note','note','manager','wide')}${button('Plan reassessment','schedule','review','wide')}`)}</aside></div>`;}
  function analyticsPage(){let completed=Object.values(state.checks).filter(Boolean).length;let max=D.tasks.length;return `<div class="stack"><div class="metric-cards"><div class="metric-card"><div class="small muted">Checked tasks · demo session</div><div class="value">${completed}</div><div class="change">of ${max} illustrative tasks</div></div><div class="metric-card"><div class="small muted">Role-specific checkpoints</div><div class="value">9</div><div class="change">Across all 3 perspectives</div></div><div class="metric-card"><div class="small muted">Support loop status</div><div class="value">${state.supportComplete?'Closed':'Open'}</div><div class="change">Human reviewed, not AI-only</div></div></div><div class="grid cols-2">${card('Milestone engagement · sample',`<div class="mini-bars">${D.days.map((d,j)=>`<div class="mini-bar"><b>Day ${d}</b><div class="progress-track" style="width:100%"><div class="progress-fill" style="width:${d<=state.day?Math.max(20,100-j*8):4}%"></div></div><span>${d<=state.day?'Active':'Future'}</span></div>`).join('')}</div>`)}${card('What a real analytics product should measure',`${row('Time to first meaningful contribution','From hire date to approved, reviewed work')}${row('Time to independently productive work','Validated autonomy against role criteria')}${row('Manager effort and response time','Actual review load, delays and escalation paths')}${row('Intervention outcomes','Whether small assistance helped unblock work')}${row('Employee confidence and belonging','Privacy-preserving pulse feedback')}`)}</div>${card('Privacy / measurement caution',`<div class="insight-banner">These are prototype figures. A production product would need baseline definitions, unbiased evidence collection, informed access controls and real longitudinal measurement before making causal claims about onboarding outcomes.</div>`)}</div>`;}
  function notesPage(){let ns=state.notes.filter(n=>n.role===state.role);return `<div class="wide-content-with-rail"><div class="stack">${card('Coaching and review notes',`${button('Create note','note',state.role,'primary')}<div style="margin-top:15px">${ns.length?ns.map(n=>`<div class="record-item"><div class="record-date">${esc(n.when)} · Day ${n.day}</div><b>${esc(n.subject)}</b><div>${esc(n.body)}</div></div>`).join(''):'<div class="empty">No notes for this role yet. Create a note to see a saved example with the intended privacy boundary.</div>'}</div>`)}${card('What belongs in a buddy note',`${row('Observed, factual support','What was discussed and what practical next step was agreed')}${row('Respectful and minimal','No speculation about traits or personal health')}${row('Shared only by choice or policy','Private coaching notes are not performance assessments')}`)}</div><aside>${buddyPermissions()}</aside></div>`;}
  function calendarPage(){return `<div class="grid cols-2">${card('Planned checkpoints',`${D.stages.map(s=>`<div class="task-row"><div><b>Day ${s.day} · ${esc(s.short)}</b><div class="tiny muted">${esc(D.story[s.day][state.role==='employee'?0:state.role==='manager'?1:2])}</div></div>${button('Open','day',s.day,'sm')}</div>`).join('')}`)}${card('Schedule a support session',`<p class="section-text">Calendar actions are simulated here. In production, the manager and buddy would use the organisation’s connected calendar and messaging platform.</p>${button('Plan short pairing session','schedule','buddy','primary wide')}${button('Schedule manager re-review','schedule','review','wide')}`)}</div>`;}
  function teamPage(){return `<div class="stack"><div class="metric-cards"><div class="metric-card"><div class="small muted">Team members</div><div class="value">8</div><div class="tiny muted">Illustrative engineering team</div></div><div class="metric-card"><div class="small muted">New joiners</div><div class="value">2</div><div class="tiny muted">Ranvijay + one sample profile</div></div><div class="metric-card"><div class="small muted">Milestone reviews</div><div class="value">2</div><div class="tiny muted">Demonstration queue</div></div></div>${card('Active new joiners',`<div class="task-row">${avatar('employee')}<div style="flex:1"><b>Ranvijay Singh</b><div class="small muted">SDE-2 · AI Deployment Engineer · Day ${state.day}</div></div>${button('Open current review','section','journey','primary')}</div><div class="task-row"><div class="mini-avatar">PK</div><div style="flex:1"><b>Priya Khanna</b><div class="small muted">Data Engineer · Example profile</div></div>${button('View sample profile','sample-profile','priya')}</div>`)}${card('Manager workflow',`${row('Review role readiness','Use organisation-approved success criteria')}${row('Approve scoped work','Maintain existing engineering controls')}${row('Act on evidence','Progress, focus learning or intervene supportively')}${button('Inspect Day 31 decision point','day',31,'primary')}`)}</div>`;}
  function secondaryMain(){let s=state.section;let body=s==='learning'?learningPage():s==='competencies'?competencyPage():s==='tasks'?tasksPage():s==='milestones'?milestonePage():s==='people'?peoplePage():s==='interventions'?interventionsPage():s==='analytics'?analyticsPage():s==='notes'?notesPage():s==='calendar'?calendarPage():s==='team'?teamPage():`<div class="empty">Section under construction</div>`;return secondaryHead()+body;}
  function render(){app.innerHTML=`<div class="app-shell">${sidebar()}<main class="main">${topbar()}<div class="page">${roleContext()}${state.section==='journey'?(state.role==='employee'?employeeMain():state.role==='manager'?managerMain():buddyMain()):secondaryMain()}<footer class="footer-note"><span>Concept demonstration · illustrative people, competency scores, assignments, resources and integration states. No live AI or enterprise connectors.</span><span>${button('Reset demo state','reset','','ghost sm')}${button('How to demo','tour','','ghost sm')}</span></footer></div></main></div>`;renderOverlay();}
  function showDrawer(kind,id=''){overlay={kind,id,mode:'drawer'};renderOverlay();}
  function showModal(kind,id=''){overlay={kind,id,mode:'modal'};renderOverlay();}
  const dismiss=()=>{overlay=null;renderOverlay();};
  function renderOverlay(){if(!overlay){overlayRoot.innerHTML='';return;}const o=overlay;const content=overlayContent(o.kind,o.id);if(!content){overlay=null;overlayRoot.innerHTML='';return;}const top=`<div class="drawer-title">${content.title}</div><div class="drawer-sub">${content.sub||''}</div>`;const closeBtn=`<button class="icon-button" data-action="close" aria-label="Close panel">${i('x',19)}</button>`;overlayRoot.innerHTML=`<div class="overlay-scrim" data-action="close"></div>${o.mode==='modal'?`<div class="modal-wrap"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(content.title)}"><div class="modal-head"><div>${top}</div>${closeBtn}</div><div class="modal-body">${content.body}</div>${content.footer?`<div class="modal-foot">${content.footer}</div>`:''}</div></div>`:`<aside class="drawer" role="dialog" aria-modal="true" aria-label="${esc(content.title)}"><div class="drawer-top"><div>${top}</div>${closeBtn}</div><div class="drawer-body">${content.body}</div><div class="drawer-footer">${content.footer||button('Close','close','','soft')}</div></aside>`}`;}
  function formField(label,name,value='',placeholder='',type='text'){return `<label class="form-label" for="field-${esc(name)}">${esc(label)}</label><input class="field" id="field-${esc(name)}" type="${type}" name="${esc(name)}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${type==='date'?'':'required'}/>`;}
  function textArea(label,name,value='',placeholder=''){return `<label class="form-label" for="field-${esc(name)}">${esc(label)}</label><textarea class="field textarea" id="field-${esc(name)}" name="${esc(name)}" placeholder="${esc(placeholder)}" required>${esc(value)}</textarea>`;}
  function guidePanel(title,items){return `<div class="mini-feature tinted"><div class="mini-title">${esc(title)}</div><div class="ordered">${items.map((x,j)=>`<div class="ordered-item"><span class="number-circle">${j+1}</span><div class="small">${esc(x)}</div></div>`).join('')}</div></div>`;}
  function overlayContent(kind,id){
    if(kind==='explorer')return {title:'Explore the whole 120-day journey',sub:'Jump to any checkpoint and open its Employee, Manager or Human Buddy experience. Role switches preserve the day.',body:`<div class="insight-banner">This is one coordinated workflow from hire to productive work. Each row shows what the three actors do at the <b>same checkpoint</b>. Select any cell to jump into that experience.</div><div class="journey-matrix"><div class="matrix-header">Day</div><div class="matrix-header">${i('briefcase',14)} Employee</div><div class="matrix-header">${i('layout-dashboard',14)} Manager</div><div class="matrix-header">${i('headphones',14)} Human Buddy</div>${D.days.map(day=>`<div class="matrix-day">Day ${day}<div class="tiny muted">${D.stages.find(s=>s.day===day).tag}</div></div>${['employee','manager','buddy'].map((r,index)=>`<button class="matrix-cell ${state.day===day&&state.role===r?'current':''}" data-action="jump" data-id="${r}:${day}"><b>${esc(D.stages.find(s=>s.day===day).short)}</b><span>${esc(D.story[day][index])}</span><span class="linkish">Open Day ${day} ${D.roles[r].label} ${i('arrow-right',11)}</span></button>`).join('')}`).join('')}</div><div class="insight-banner success"><b>Demonstration scenario:</b> At Day 31, switch the outcome between “Completed” and “Needs support”; then switch between the Manager, Human Buddy and Employee to see how the decision flows.</div>`,footer:`${button('Reset view to Day 1','jump','employee:1','soft')}${button('Close explorer','close','','primary')}`};
    if(kind==='resource'||kind==='learning-drawer') {const r=resourceById(id)||D.resources[0];return {title:r.title,sub:`${r.type} · ${r.minutes} minute recommended resource`,body:`${pill(r.type,'indigo')} ${pill(state.resourcePlan[r.id]?'In learning plan':'Optional suggested resource',state.resourcePlan[r.id]?'green':'indigo')}<p style="font-size:13px;color:#52628a">${esc(r.detail)}</p>${guidePanel('What you should learn or do',r.contents)}<div class="insight-banner"><b>Why this appears:</b> This material was selected because the current role, task or review identified ${esc(r.tags[0])} as relevant. A real deployment would deep-link to an organisation-approved learning source.</div><h3 class="panel-title">Apply it to meaningful work</h3>${row('Review the approved example','Record what a good solution looks like')}${row('Try one work-adjacent exercise','Capture a test result or an explanation')}${row('Discuss it with your reviewer or buddy','Make learning evidence-based')}<div class="note-banner" style="margin-top:15px">P0 simulates the resource viewer; there is no externally hosted training material or real learning management system behind this demo.</div>`,footer:`${button(state.resourceDone[r.id]?'✓ Read and reviewed':'Mark as read / reviewed','resource-done',r.id,'green')}${button(state.resourcePlan[r.id]?'Remove from my plan':'Add to learning plan','resource-plan',r.id,'primary')}`};}
    if(kind==='task'){const t=taskById(id);if(!t)return null;return {title:t.title,sub:`Day ${t.day} · ${t.category}`,body:`${pill(state.checks[t.id]?'Marked complete':'Needs action',state.checks[t.id]?'green':'amber')} ${pill(t.duration,'indigo')}<p style="font-size:13px;color:#586a8b">${esc(t.description)}</p>${guidePanel('Expected actions',[`Review the authorised task context and its scope.`,`Carry out: ${t.title.toLowerCase()}.`,`Capture a short explanation or suitable work evidence.`,`Seek review/approval where your manager or organisation requires it.`])}${t.resource?`<h3 class="panel-title" style="margin-top:18px">Linked reference</h3>${resourceRows([t.resource])}`:''}<div class="insight-banner">${t.day===1?'HR/IT systems retain their own confirmation records. Checking a box here is only a local demo action.':t.day>=30?'This does not merge or replace the engineering issue tracker, pull request or deployment approval.':'Practical work and reviewer feedback are more informative than a content-consumption metric.'}</div>`,footer:`${button('Attach / record work evidence','submit-evidence',t.id)}${button(state.checks[t.id]?'Reopen action':'Mark action complete','check',t.id,'primary')}`};}
    if(kind==='competency'){let c=D.competencies.find(x=>x.name===id);if(!c)return null;return {title:c.name,sub:'Role competency · evidence-linked provisional proficiency',body:`<div class="grid cols-2"><div class="mini-feature"><div class="tiny muted">Current illustrative level</div><div class="stat-num">${c.current.toFixed(1)} / 5</div></div><div class="mini-feature"><div class="tiny muted">Role requirement</div><div class="stat-num">${c.required.toFixed(1)} / 5</div></div></div><h3 class="panel-title" style="margin-top:20px">Evidence that supports the interpretation</h3><div class="insight-banner">${esc(c.evidence)}</div>${guidePanel('How an official update should occur',['Locate the original work artefact, code review or assessment.','Determine what proficiency was actually demonstrated, and whether conditions were representative.','Ask a manager or authorised assessor to validate the proposed change.','Retain a link to the decision and communicate development recommendations.'])}<div class="note-banner">Illustrative numeric values are not a production-grade proficiency scoring model. A single task should not mechanically increment a competency by a fixed score.</div>`,footer:`${button('View supporting evidence','evidence','milestone')}${button('Request manager validation','message-manager','competency','primary')}`};}
    if(kind==='ticket'){return {title:'ENG-218 · Inference service reliability',sub:'Sample work item · remains in Jira / Azure DevOps in a production deployment',body:`${pill('Day 30 · real-work adjacent','indigo')} ${pill(state.approvals.day30?'Manager approved':'Manager approval required',state.approvals.day30?'green':'amber')}<h3>Improve inference service reliability in staging by adding structured logging and bounded retry handling</h3><p class="muted">The objective is to improve debuggability and graceful failure handling within a constrained inference service under normal engineering checks.</p>${guidePanel('Expected acceptance criteria',['Create a reviewed branch linked to the existing team issue.','Use structured logs containing relevant context without exposing secrets.','Introduce bounded, safe retries with appropriate failure modes and idempotency considerations.','Run local and staging tests; document expected and observed outcomes.','Address reviewer comments, explain rollback and close the PR with evidence.'])}<div class="insight-banner"><b>Why suggested:</b> Python engineering is strong, but deployment reliability and observability need applied evidence. This is a bounded task, not an AI-selected production change.</div><h3 class="panel-title">Approval and visibility</h3>${row('Aditi Rao','Approves scope, allocation, acceptance and milestone')}${row('Ranvijay Singh','Owns implementation, evidence and reviewer conversation')}${row('Karan Mehta','Optional peer support, no final assessment authority')}`,footer:`${button('Inspect available evidence','evidence','day30')}${state.role==='manager'?button('Manager approval','approve-ticket','day30','primary'):button('See manager’s decision','role','manager','primary')}`};}
    if(kind==='evidence') {const entries=state.activities.slice(0,7);return {title:'Reviewable work and learning evidence',sub:`Day ${state.day} · ${id==='day31'?'Ticket outcome':id==='day14'?'Review comments':'Milestone and task record'}`,body:`<div class="insight-banner"><b>Traceability principle:</b> every assessment and recommendation should point to reviewable source evidence, not just a completion checkbox.</div>${guidePanel('Evidence expected from an engineering task',['Linked Jira / Azure DevOps issue and approved acceptance criteria','Git branch, pull request, reviewer comments and accepted changes','Local and staging test reports with reproducible steps','Observability logs, metric snapshots and release-control evidence','Manager’s qualitative review and final next-step decision'])}<h3 class="panel-title" style="margin-top:20px">Illustrative evidence register</h3><div class="task-row"><div>${i('code',16)} <b>ENG-218 · Reliability ticket</b><div class="tiny muted">Source: hypothetical linked work tracker</div></div>${pill('Demo','indigo')}</div><div class="task-row"><div>${i('file',16)} <b>PR #184 · Review notes and tests</b><div class="tiny muted">Source: hypothetical engineering repository</div></div>${pill(state.scenario==='success'?'Accepted':'Needs work',state.scenario==='success'?'green':'amber')}</div><div class="task-row"><div>${i('chart',16)} <b>Staging validation report</b><div class="tiny muted">Source: simulated runbook evidence</div></div>${pill(state.scenario==='success'?'Valid':'Pending',state.scenario==='success'?'green':'amber')}</div>${entries.length?`<h3 class="panel-title" style="margin-top:20px">Your demo interaction history</h3>${entries.map(e=>`<div class="record-item"><div class="record-date">${esc(e.time)} · ${esc(e.role)} · Day ${e.day}</div>${esc(e.label)}</div>`).join('')}`:''}<div class="note-banner">This prototype does not fetch code, Jira, private HR data or real employee assessment records.</div>`,footer:`${button('Add evidence note','submit-evidence','generic')}${button('Close review','close','','primary')}`};}
    if(kind==='permissions')return {title:'Access boundaries and data minimisation',sub:'A P0 permission model for employee, manager and human buddy',body:`${guidePanel('Who can see what',['Employee: own plan, reviewed milestones, suggested learning and private assistance.','Manager: authorised work evidence, role requirements, intervention proposals and decision controls.','Human buddy: authorised task context, selected support request and useful learning cues only.','HR: owns HR obligations, policy acknowledgements, sensitive employment data and access approvals.'])}<div class="insight-banner warn"><b>Not shared with buddies:</b> pay information, private HR files, detailed performance evaluations, medical information, private AI-buddy chats or speculative psychological labels.</div>${button('See Karan’s view','role','buddy','primary')}`};
    if(kind==='manager-action'||kind==='coach') {const [day,n]=id.split(':').map(Number);const c=kind==='coach'?D.buddyDays[day]:D.managerDays[day];const action=c.actions[n]||'Review the task';return {title:action,sub:`Day ${day} · ${kind==='coach'?'Human buddy coaching':'Manager decision guide'}`,body:`<div class="insight-banner">${esc(c.focus)}</div>${guidePanel('What is expected',[`Clarify what success looks like for: ${action.toLowerCase()}.`,'Locate one relevant work artefact, review comment or approved reference.','Speak with the employee and invite their explanation before assigning a label.','Agree the next specific, proportionate action and any follow-up.'])}${kind==='coach'?`<div class="note-banner">Karan can support but cannot overrule Aditi’s work approval or access private employee records.</div>`:`<div class="note-banner">Only Aditi or an authorised manager can make this an official readiness or task assignment decision.</div>`}`,footer:`${button('Record a note','note',kind==='coach'?'buddy':'manager')}${button('Schedule follow-up','schedule','review','primary')}`};}
    if(kind==='notifications'){return {title:'Notifications and pending work',sub:`Sample activity for ${D.roles[state.role].label}`,body:`${[['Today','Day '+state.day+' checkpoint ready','Review current expectations and linked tasks.'],['Pending','Engineering review / confirmation','A human decision or source evidence is required.'],['Suggested','Cross-role coordination','Switch to the corresponding manager or buddy view.']].map(([when,title,detail])=>`<div class="list-check">${i('bell',16)}<div style="flex:1"><b>${title}</b><p>${when} · ${detail}</p></div>${button('Open','section','journey','sm')}</div>`).join('')}<h3 class="panel-title" style="margin-top:20px">Recent demo actions</h3>${state.activities.length?state.activities.slice(0,8).map(x=>`<div class="record-item"><div class="record-date">${esc(x.time)} · ${esc(x.role)}</div>${esc(x.label)}</div>`).join(''):'<div class="empty">No recorded actions yet. Try completing a task, adding a note or approving a work item.</div>'}`,footer:button('Open current checkpoint','section','journey','primary')};}
    if(kind==='profile'){let r=D.roles[state.role];return {title:r.person,sub:r.title,body:`<div class="role-id">${avatar(state.role,true)}<div><div class="name">${r.person}</div><div class="sub">Active perspective: ${r.label}</div></div></div><div class="insight-banner">This is a fully illustrative demo using fictional people and sample organisation data. It stores changes in this browser only.</div>${button('View journey explorer','explorer','','wide')}${button('Inspect data permissions','permissions','','wide')}${button('Reset demo state','reset','','danger wide')}`};}
    if(kind==='help')return {title:'Request human buddy support',sub:`Day ${state.day} · routed to Karan Mehta`,body:`<div class="insight-banner">A request gives Karan a concise, authorised description of what you need, not access to private AI chats or your complete appraisal history.</div><form data-form="help">${formField('Help topic','subject',state.day===31?'Retry handling and staging validation':'Guidance with my current milestone')}${textArea('What would help?','body','I would appreciate a 20-minute walkthrough and one concrete next step.')}<label class="toggle-row"><input type="checkbox" name="shareTask" checked/> Include the current task brief and relevant learning cues</label><button class="btn primary wide" type="submit" style="margin-top:15px">${i('send',15)} Send support request (demo)</button></form>`};
    if(kind==='note') {const subj=state.role==='manager'?'Manager checkpoint':state.role==='buddy'?'Coaching note':'Learning reflection';return {title:'Record a '+subj.toLowerCase(),sub:`Day ${state.day} · recorded as ${D.roles[state.role].label}`,body:`<form data-form="note">${formField('Note title','subject',`Day ${state.day} · ${subj}`)}${textArea('Observation, evidence or agreed next step','body','What was actually observed? What should happen next?')}<label class="form-label" for="field-visibility">Who can view this note?</label><select class="field" name="visibility" id="field-visibility"><option value="private">Private to this role (default)</option><option value="shared">Share a factual summary with the relevant participant</option></select><div class="insight-banner">Avoid unsupported psychological labels and personal HR details. Notes in this demo live only in your browser.</div><button class="btn primary wide" type="submit">${i('check',15)} Save note</button></form>`};}
    if(kind==='draft-message')return {title:'Edit and send buddy invitation',sub:'Simulated message · the employee can see a sent communication',body:`<form data-form="message"><div class="insight-banner">A human buddy message should be short, actionable and reassuring without promising any assessment result.</div>${formField('To','to','Ranvijay Singh')}${formField('Subject','subject',`Day ${state.day} support · 20-minute pairing`)}${textArea('Message','body',state.day===31?'Hi Ranvijay, Aditi asked me to help with the reliability ticket. Let’s spend 20–30 minutes understanding what blocked you and working through one next step. You can drive the changes, and I’ll help you reason through the options.':'Hi Ranvijay, welcome! I’m Karan, your human buddy. Happy to talk through your current task, explain team norms or help you navigate the tools. We can arrange a short pairing session.')}<button type="submit" class="btn primary wide">${i('send',15)} Send edited draft (demo)</button></form>`};
    if(kind==='message-manager')return {title:'Message Aditi Rao',sub:'Simulated manager communication · share factual updates',body:`<form data-form="message"><div class="insight-banner">Use an appropriate, concise work-related summary. Manager-facing messages should not include private peer conversations without consent.</div>${formField('To','to','Aditi Rao')}${formField('Subject','subject',state.role==='buddy'?`Day ${state.day} · Buddy support update`:`Day ${state.day} · Milestone check-in`)}${textArea('Your message','body',state.role==='buddy'?'Hi Aditi, I reviewed the task context with Ranvijay. We identified the immediate technical blocker and agreed on an independent next step. I recommend another review after the retry.':'Hi Aditi, I’ve reviewed the milestone requirements and the linked learning. I would appreciate a quick check-in to confirm the next scoped work item.')}<button type="submit" class="btn primary wide">${i('send',15)} Send note (demo)</button></form>`};
    if(kind==='schedule')return {title:'Schedule a checkpoint or pairing session',sub:'Prototype event creation · no live Calendar connection',body:`<form data-form="schedule">${formField('Meeting title','subject',id==='buddy'?'20-minute buddy pairing':id==='week5'?'Week 5 milestone checkpoint':`Day ${state.day} manager review`)}${formField('Date','date',new Date(Date.now()+24*3600*1000).toISOString().slice(0,10),'','date')}<label class="form-label" for="field-time">Local time</label><select name="time" class="field" id="field-time"><option>10:00</option><option>11:30</option><option selected>14:30</option><option>16:00</option></select>${textArea('Agenda','body',`Review Day ${state.day} progress, discuss blockers, agree evidence and a small next action.`)}<div class="insight-banner">This saves a demo event locally. A real implementation should connect to the organisation’s calendar and send invitations through approved channels.</div><button type="submit" class="btn primary wide">${i('calendar',15)} Save sample meeting</button></form>`};
    if(kind==='tag-buddy')return {title:'Assign Karan a focused support brief',sub:'Manager-approved, privacy-limited assistance',body:`<form data-form="tag-buddy"><div class="ai-summary"><strong>${i('sparkles',17)} Suggested buddy brief</strong>Ranvijay set up the branch, added partial logging, and passed local tests. He needs help with bounded retry logic, staging validation, interpreting failure logs and choosing a focused independent next step.</div>${formField('Assigned buddy','to','Karan Mehta')}${textArea('What the buddy should help with','body','Please help Ranvijay reason through retry failure modes and staging checks. Let him implement the next step independently, and send me a concise factual update afterwards.')}<label class="toggle-row"><input type="checkbox" name="shareTask" checked/> Share the scoped ticket and recommended learning only</label><button type="submit" class="btn primary wide">${i('send',15)} Send authorised brief (demo)</button></form>`};
    if(kind==='approve-ticket')return {title:state.approvals.day30?'Ticket approval record':'Approve a proposed first real ticket',sub:'Aditi Rao · authorises task selection and acceptance criteria',body:`<form data-form="approve-ticket"><div class="insight-banner"><b>Proposed work:</b> Improve inference-service reliability in staging through structured logging and bounded retries.</div>${guidePanel('Approval checklist',['Scope is bounded and engineering backlog item is legitimate.','Acceptance criteria include code quality, tests and review.','Staging validation, permissions and release constraints are understood.','A specific engineer/reviewer will provide feedback.'])}<label class="toggle-row"><input type="checkbox" name="criteria" required checked/> I confirm this is appropriate work within team process and risk controls.</label>${textArea('Manager approval note','body','Approved as a bounded first contribution with standard code review, tests and safe staging validation.')}<button class="btn primary wide" type="submit">${i('check-circle',16)} Record manager approval</button></form>`};
    if(kind==='revise-ticket')return {title:'Revise the suggested ticket scope',sub:'Human manager decision · AI suggestions are editable',body:`<form data-form="revise-ticket">${formField('Updated ticket title','subject','Improve inference service reliability in staging')}${textArea('Revised acceptance criteria','body','Require bounded retry logic, structured logs, tested failure cases, staging review and a rollback-aware PR. Limit changes to the non-critical inference service.')}<div class="insight-banner">A revised scope returns to manager approval. The P0 should never silently rewrite a live engineering issue.</div><button class="btn primary wide" type="submit">Save revised suggestion (demo)</button></form>`};
    if(kind==='assign-next'){const choice={'option-1':'Own a larger inference-service improvement','option-2':'Add monitoring and alerting to the service','option-3':'Take a bounded reliability backlog item'}[state.selectedTicket];return {title:'Approve the next scoped work item',sub:'Growth path · Day 31 manager decision',body:`<form data-form="assign-next"><div class="insight-banner success"><b>Selected:</b> ${esc(choice||'Broader scoped reliability task')}. This recommendation is advisory and requires managerial approval.</div>${formField('Proposed assignment','subject',choice)}${textArea('Scope and guardrails','body','Scope is limited, accepted by the team, and reviewed under normal engineering workflows. Buddy support remains available if required.')}<label class="toggle-row"><input type="checkbox" checked name="criteria" required/> I have reviewed evidence, scope, risk and reviewer ownership.</label><button type="submit" class="btn primary wide">${i('check-circle',15)} Approve next task (demo)</button></form>`};}
    if(kind==='complete-support')return {title:'Close the focused buddy support loop',sub:'A supportive coaching outcome, not an employee performance verdict',body:`<form data-form="support-complete">${textArea('What practical support occurred?','body','We walked through the failing example, reviewed the logs, and agreed that Ranvijay would implement and test the next retry change himself.')}<label class="toggle-row"><input type="checkbox" name="shareTask" checked/> Send a factual follow-up summary to Aditi</label><div class="insight-banner">Support completion does not automatically raise proficiency or close the engineering ticket. The manager reviews any new evidence.</div><button type="submit" class="btn primary wide">${i('check-circle',15)} Record support complete</button></form>`};
    if(kind==='submit-evidence')return {title:'Attach a work-evidence record',sub:'Simulated reference to an existing task tracker or pull request',body:`<form data-form="evidence">${formField('Evidence label','subject',`Day ${state.day} · ${id==='sandbox'?'Sandbox demo':id==='day30'?'Reliability ticket':'Work artefact'}`)}${formField('Reference or issue link (illustrative)','ref','ENG-218 / PR #184')}${textArea('What does this demonstrate?','body','Explain what was done, test evidence, known limitations and where a reviewer can confirm the result.')}<div class="insight-banner">This records text in the local demo only. No attachment is uploaded and no external repository is accessed.</div><button type="submit" class="btn primary wide">${i('check',15)} Record evidence reference</button></form>`};
    if(kind==='escalate')return {title:'Escalate a legitimate blocker',sub:'Route the issue to the engineering manager, without bypassing controls',body:`<form data-form="escalate">${formField('Reason for escalation','subject','Blocked on staging validation / release review')}${textArea('Facts and requested decision','body','Please review the specific blocker, its impact, what has been tried and whether an authorised engineer needs to intervene.')}<button type="submit" class="btn primary wide">${i('send',15)} Record escalation (demo)</button></form>`};
    if(kind==='recovery-task')return {title:'Recommend a small recovery exercise',sub:'Buddy suggests; manager approves if it changes scope',body:`<form data-form="recovery-task">${formField('Small next action','subject','Implement bounded retry and validate one failure mode')}${textArea('How to assess it','body','Run one safe local test with observable logs, document the result and request review from Aditi’s designated engineer.')}<button type="submit" class="btn primary wide">${i('send',15)} Send recommendation to manager</button></form>`};
    if(kind==='sample-profile')return {title:'Priya Khanna · sample employee',sub:'Illustrative placeholder profile, not part of this Ranvijay ramp walkthrough',body:`<div class="insight-banner">This prototype is intentionally deep for one employee across three roles, rather than creating a shallow fake dataset for dozens of people.</div>${button('Return to Ranvijay','section','journey','primary')}`};
    if(kind==='reset')return {title:'Reset the local demonstration?',sub:'This clears saved demo interactions and returns to Employee Day 1',body:`<div class="insight-banner warn">This will clear locally stored checkmarks, messages, review notes, recorded approvals, support status and meeting examples. No external systems are affected.</div><div class="btn-grid">${button('Cancel','close','','soft')}${button('Reset all demo state','confirm-reset','','danger')}</div>`};
    if(kind==='tour')return {title:'Demo walkthrough · show the closed loop',sub:'Suggested five-minute founder / engineering manager demonstration',body:`${guidePanel('Recommended live sequence',['Employee Day 1: HR essentials, expectations and support people.','Day 5 Employee: learn the stack, run a sandbox and submit evidence.','Day 14 Employee: reviewed work triggers targeted learning and another attempt.','Day 30 Manager: approve a meaningful, low-risk engineering ticket.','Day 31 Manager: view success and blocked outcomes; send a buddy brief in the blocked path.','Day 31 Human Buddy: coach and share limited factual support progress.','Day 60 Employee: see growing responsibility rather than more generic courses.','Use Journey Explorer to switch day and perspective in a single click.'])}<div class="insight-banner">The demo stores state in your browser, works without external APIs, and labels synthetic profiles, scores and evidence as illustrative.</div>`,footer:`${button('Open journey explorer','explorer','','soft')}${button('Start demo at Day 1','jump','employee:1','primary')}`};
    return null;
  }
  function answerQuestion(question){const q=question.toLowerCase();if(/next|unlock|milestone/.test(q))return `The next step follows reviewed work evidence, not calendar time or XP alone. After Day ${state.day}, Aditi checks quality, role fit, risk, and any remaining learning need before approving wider scope.`;if(/why.*learn|resource|learning/.test(q))return `Learning is recommended because your actual role and recent review evidence point to a specific skill need. The shortest approved resource is paired with a concrete exercise and a chance to retry. Generic courses are avoided when you already have the foundations.`;if(/retry|staging|failure|debug/.test(q))return `For the reliability task, begin with one failing case. Inspect structured logs, decide whether the operation is safe to retry, cap retry attempts and backoff, then validate locally and in approved staging. Record the evidence for review. Ask Karan for a focused pairing session if you remain blocked.`;if(/day 1|hr|policy|access/.test(q))return `Day 1 is about access, essential policy awareness, belonging and expectations. Follow the HR and IT links; your manager and human buddy can explain the process, but cannot access private HR records.`;if(/task|ticket|work/.test(q))return `Your current assignment is linked to a real role capability and an approved work scope. Read the brief, explain the acceptance criteria, complete the next bounded step, and collect test or review evidence. Aditi makes consequential work-assignment decisions.`;return `For Day ${state.day}, your focus is ${D.employeeDays[state.day].title.toLowerCase()}. Start with the smallest relevant work task, use an approved learning reference if needed, then discuss what the evidence actually shows. This is a scripted demo reply, not a live AI assistant.`;}
  function sendChat(question){question=String(question||'').trim();if(!question)return;state.buddyChat.push({by:'You',text:question},{by:'eBuddy · sample',text:answerQuestion(question)});state.buddyChat=state.buddyChat.slice(-25);save();render();toast('eBuddy returned a sample, context-aware response');}
  function handleAction(action,id){
    switch(action){
      case 'close':dismiss();return;
      case 'mobile':mobileOpen=!mobileOpen;render();return;
      case 'role':mobileOpen=false;setRole(id);return;
      case 'day':mobileOpen=false;setDay(id);return;
      case 'jump':{const [r,d]=id.split(':');state.role=r;state.day=Number(d);state.section='journey';save();overlay=null;mobileOpen=false;render();window.scrollTo({top:0,behavior:'smooth'});return;}
      case 'section':mobileOpen=false;setSection(id);return;
      case 'scenario':state.scenario=id;save();overlay=null;render();toast(id==='support'?'Day 31 now shows the buddy-supported recovery scenario':'Day 31 now shows the successful-ticket growth scenario');return;
      case 'check':state.checks[id]=!state.checks[id];overlay=null;logActivity(`${state.checks[id]?'Completed':'Reopened'} task: ${taskById(id)?.title||id}`);render();toast(state.checks[id]?'Demo action marked complete':'Action reopened');return;
      case 'resource-plan':state.resourcePlan[id]=!state.resourcePlan[id];logActivity(`${state.resourcePlan[id]?'Added to':'Removed from'} learning plan: ${resourceById(id)?.title||id}`);render();toast(state.resourcePlan[id]?'Resource added to your learning plan':'Resource removed from learning plan');return;
      case 'resource-done':state.resourceDone[id]=!state.resourceDone[id];logActivity(`${state.resourceDone[id]?'Reviewed':'Reopened'} learning: ${resourceById(id)?.title||id}`);render();toast(state.resourceDone[id]?'Learning resource marked reviewed':'Learning resource reopened');return;
      case 'select-ticket':state.selectedTicket=id;save();render();toast('Next-ticket option selected. Aditi must still approve.');return;
      case 'quick-question':sendChat(id);return;
      case 'confirm-reset':state=JSON.parse(JSON.stringify(defaults));save();overlay=null;render();toast('All local demo state reset');return;
      case 'explorer':showModal('explorer');return;
      case 'tour':showModal('tour');return;
      case 'reset':showDrawer('reset');return;
      case 'notifications':case 'profile':case 'resource':case 'task':case 'competency':case 'ticket':case 'evidence':case 'permissions':case 'manager-action':case 'coach':case 'learning-drawer':case 'help':case 'note':case 'draft-message':case 'message-manager':case 'schedule':case 'tag-buddy':case 'approve-ticket':case 'revise-ticket':case 'assign-next':case 'complete-support':case 'submit-evidence':case 'escalate':case 'recovery-task':case 'sample-profile':showDrawer(action,id);return;
      default:toast('This action is not available in the demo');
    }
  }
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();handleAction(b.dataset.action,b.dataset.id||'');});
  document.addEventListener('submit',e=>{
    const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const data=Object.fromEntries(new FormData(f).entries());const name=f.dataset.form;
    if(name==='chat'){sendChat(data.message);return;}
    if(name==='search-resources'){state.filters.resource=String(data.query||'').trim();save();render();return;}
    let message='Demo action recorded';let keep=false;
    if(name==='note'){state.notes.unshift({role:state.role,day:state.day,when:new Date().toLocaleString(),subject:data.subject||'Untitled',body:data.body||'',visibility:data.visibility||'private'});message='Note saved in local demo';logActivity(`Recorded ${state.role} note: ${data.subject}`);}
    else if(name==='message'){state.messages.unshift({role:state.role,day:state.day,when:new Date().toLocaleString(),to:data.to,subject:data.subject,body:data.body});message=`Message to ${data.to} recorded (demo; not actually sent)`;logActivity(`Composed demo message to ${data.to}`);}
    else if(name==='help'){state.messages.unshift({role:'employee',day:state.day,when:new Date().toLocaleString(),to:'Karan Mehta',subject:data.subject,body:data.body});message='Support request created for Karan (demo)';logActivity(`Requested human buddy help: ${data.subject}`);}
    else if(name==='schedule'){state.followUpScheduled=true;state.activities.unshift({role:state.role,day:state.day,time:new Date().toLocaleString(),label:`Scheduled example session: ${data.subject} on ${data.date} at ${data.time}`});message='Demo session saved locally; no real invitations sent';}
    else if(name==='tag-buddy'){state.messages.unshift({role:'manager',day:state.day,when:new Date().toLocaleString(),to:'Karan Mehta',subject:'Day 31 support request',body:data.body});message='Karan received an illustrative task-limited support brief';logActivity('Aditi tagged Karan with authorised buddy support brief');}
    else if(name==='approve-ticket'){state.approvals.day30=true;state.notes.unshift({role:'manager',day:30,when:new Date().toLocaleString(),subject:'ENG-218 ticket approval',body:data.body,visibility:'shared'});message='Sample engineering ticket approved by Aditi';logActivity('Aditi approved the bounded first contribution');}
    else if(name==='revise-ticket'){state.approvals.day30=false;state.notes.unshift({role:'manager',day:30,when:new Date().toLocaleString(),subject:`Revised ticket: ${data.subject}`,body:data.body,visibility:'private'});message='Revised scope saved, awaiting a new approval';logActivity('Aditi revised the suggested engineering scope');}
    else if(name==='assign-next'){state.approvals.next=true;state.notes.unshift({role:'manager',day:31,when:new Date().toLocaleString(),subject:`Next task approved: ${data.subject}`,body:data.body,visibility:'shared'});message='Next scoped engineering task approved (demo)';logActivity('Aditi approved the selected next work item');}
    else if(name==='support-complete'){state.supportComplete=true;state.notes.unshift({role:'buddy',day:31,when:new Date().toLocaleString(),subject:'Focused support completed',body:data.body,visibility:data.shareTask?'shared':'private'});message='Focused coaching recorded; manager re-review still required';logActivity('Karan completed the focused support session');}
    else if(name==='evidence'){state.notes.unshift({role:state.role,day:state.day,when:new Date().toLocaleString(),subject:`Evidence: ${data.subject}`,body:`${data.ref} · ${data.body}`,visibility:'shared'});message='Evidence reference recorded in local demo';logActivity(`Added work evidence reference: ${data.subject}`);}
    else if(name==='escalate'){state.notes.unshift({role:state.role,day:state.day,when:new Date().toLocaleString(),subject:`Escalation: ${data.subject}`,body:data.body,visibility:'shared'});message='Escalation recorded for manager (demo)';logActivity(`Escalated blocker: ${data.subject}`);}
    else if(name==='recovery-task'){state.notes.unshift({role:'buddy',day:31,when:new Date().toLocaleString(),subject:`Recovery recommendation: ${data.subject}`,body:data.body,visibility:'shared'});message='Recovery suggestion recorded for Aditi to approve';logActivity('Karan suggested a bounded recovery exercise');}
    else {keep=true;message='Form completed';}
    save();if(!keep)overlay=null;render();toast(message);
  });
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&overlay)dismiss();});
  render();
})();
